#include <iostream>
#include <string>
#include <iomanip>

using namespace std;

int main() {
    string s, t;
    cin >> s >> t;

    int shours = stoi(s.substr(0, 2));
    int thours = stoi(t.substr(0, 2));
    int smins = stoi(s.substr(3));
    int tmins = stoi(t.substr(3));

    int answerhours = shours - thours;
    if (answerhours < 0)
        answerhours += 24;

    int answermins = smins - tmins;
    if (answermins < 0) {
        answermins += 60;
        answerhours--;
        if (answerhours < 0)
            answerhours = 23;
    }

    cout << setw(2) << setfill('0') << answerhours << ":"
         << setw(2) << setfill('0') << answermins << endl;

    return 0;
}

